package com.jnapanam.sportszone.content.dto;import com.jnapanam.sportszone.content.model.*;import java.util.UUID;public record GalleryResponse(UUID id,String title,String titleKn,MediaType mediaType,String mediaUrl,String thumbnailUrl,String altText,String altTextKn,String sportCode,boolean published,int displayOrder){public static GalleryResponse from(GalleryItem g){return new GalleryResponse(g.getId(),g.getTitle(),g.getTitleKn(),g.getMediaType(),g.getMediaUrl(),g.getThumbnailUrl(),g.getAltText(),g.getAltTextKn(),g.getSport()==null?null:g.getSport().getCode(),g.isPublished(),g.getDisplayOrder());}}